import { Link, useLocation } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import { useState } from 'react';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { href: '#about', label: 'About' },
    { href: '#work', label: 'Work' },
    { href: '#contact', label: 'Contact' },
  ];

  const handleNavClick = (href: string) => {
    setIsMobileMenuOpen(false);
    if (href.startsWith('#')) {
      const el = document.querySelector(href);
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-background/90 backdrop-blur-sm">
      <div className="max-w-6xl mx-auto px-8 md:px-12">
        <div className="flex h-20 md:h-24 items-center justify-between">
          {/* Logo */}
          <Link to="/" className="flex items-center shrink-0" aria-label="Marcus Webb home">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="MW"
              className="h-9 md:h-11 w-auto object-contain shrink-0 self-center"
            />
          </Link>

          {/* Desktop nav */}
          <nav className="hidden md:flex items-center gap-10">
            {navItems.map((item) => (
              <button
                key={item.href}
                onClick={() => handleNavClick(item.href)}
                className="relative text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors duration-200 group py-1 bg-transparent border-none cursor-pointer font-sans"
              >
                {item.label}
                <span className="absolute bottom-0 left-0 h-px w-0 bg-primary transition-all duration-200 group-hover:w-full" />
              </button>
            ))}
          </nav>

          {/* Mobile toggle */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 text-foreground"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>
        </div>

        {/* Mobile menu */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-6">
            <nav className="flex flex-col gap-5">
              {navItems.map((item) => (
                <button
                  key={item.href}
                  onClick={() => handleNavClick(item.href)}
                  className="text-sm tracking-widest uppercase text-muted-foreground hover:text-foreground transition-colors text-left bg-transparent border-none cursor-pointer font-sans"
                >
                  {item.label}
                </button>
              ))}
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

export default function Footer() {
  return (
    <footer className="border-t border-border bg-background">
      <div className="max-w-6xl mx-auto px-8 md:px-12 py-8">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-2">
          <span className="text-xs tracking-widest uppercase text-muted-foreground">
            © 2026 Marcus Webb
          </span>
          <span className="text-xs tracking-widest uppercase text-muted-foreground">
            Designed with intention
          </span>
        </div>
      </div>
    </footer>
  );
}
